const isEnabled = document.getElementById('ai4a11y-define-styles') !== null;
if (!isEnabled) return true;

const lead = document.getElementById('prose-lead');
const span = lead.querySelector('.ai4a11y-define[tabindex="0"]');
if (!span) return false;

span.focus();
span.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
await new Promise(r => setTimeout(r, 50));

const tip = document.getElementById('ai4a11y-define-tooltip');
if (!tip || tip.style.display !== 'block') {
  span.blur();
  return false;
}

const tipRect = tip.getBoundingClientRect();
const clientWidth = document.documentElement.clientWidth;

const fitsHorizontally = tipRect.left >= 0 && tipRect.right <= clientWidth + 1;

document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
span.blur();
span.dispatchEvent(new FocusEvent('focusout', { bubbles: true }));

return fitsHorizontally;
